import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix if square and binary, else adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets for efficient access and ensure symmetry
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for v in adj[i]:
                if 0 <= v < n:
                    neighbors[i].add(v)
    # Ensure undirected symmetry
    for i in range(n):
        for j in list(neighbors[i]):
            if i not in neighbors[j]:
                neighbors[j].add(i)

    # Trivial cases: edgeless or complete graph
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n
    if all(len(neighbors[i]) == n - 1 for i in range(n)):
        return list(range(n))

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * (n + 1)  # +1 for safety
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: degree in subgraph induced by a set
    def degree_in_subgraph(v, vertex_set):
        return sum(1 for u in neighbors[v] if u in vertex_set)

    # DSATUR implementation with improved tie-breaking
    def dsatur():
        color = [-1] * n
        saturation = [0] * n
        neighbor_colors = [set() for _ in range(n)]
        uncolored = set(range(n))

        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                neighbor_colors[u].add(0)
                saturation[u] = len(neighbor_colors[u])

        while uncolored:
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat = saturation[v]
                if sat > max_sat:
                    max_sat = sat
                    candidates = [v]
                elif sat == max_sat:
                    candidates.append(v)

            if not candidates:
                break

            if len(candidates) > 1:
                # Tie-break: max degree in uncolored subgraph, then random
                v = max(candidates, key=lambda x: (degree_in_subgraph(x, uncolored), random.random()))
            else:
                v = candidates[0]

            used = [False] * (n + 1)
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)

            for u in neighbors[v]:
                if color[u] == -1:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        saturation[u] = len(neighbor_colors[u])
        return color

    # RLF implementation (corrected and optimized)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: degree_in_subgraph(x, uncolored))
            S = {v}
            # U: vertices not adjacent to any in S (eligible for color c)
            U = {u for u in uncolored if u != v and all(u not in neighbors[w] for w in S)}
            # W: vertices adjacent to at least one in S (ineligible for color c)
            W = {u for u in uncolored if u != v and any(u in neighbors[w] for w in S)}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = None
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    score = sum(1 for w in neighbors[u] if w in W)
                    deg_U = degree_in_subgraph(u, U)
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or \
                       (score == best_score and deg_U == best_deg_U and (best_u is None or u < best_u)):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                if best_u is None:
                    break  # Should not happen if U non-empty
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in neighbors[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            for vertex in S:
                color[vertex] = c
            uncolored -= S
            c += 1
        return color

    # Welsh-Powell ordering
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Iterated Local Search with Kempe Chains and Color Class Reduction
    def iterated_local_search(initial_coloring, max_iter=100):
        def count_colors(col):
            return max(col) + 1 if n > 0 and max(col) >= 0 else 0

        def kempe_swap(coloring, a, b):
            # Returns a new coloring after swapping colors a and b in a random Kempe chain, or None if invalid
            visited = [False] * n
            for start in range(n):
                if not visited[start] and coloring[start] in (a, b):
                    stack = [start]
                    visited[start] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for nb in neighbors[node]:
                            if not visited[nb] and coloring[nb] in (a, b):
                                visited[nb] = True
                                stack.append(nb)
                    # Try swapping this component
                    new_coloring = coloring[:]
                    valid = True
                    for node in component:
                        for nb in neighbors[node]:
                            if nb not in component and new_coloring[nb] == (a if new_coloring[node] == b else b):
                                valid = False
                                break
                        if not valid:
                            break
                    if valid:
                        for node in component:
                            new_coloring[node] = a if new_coloring[node] == b else b
                        return new_coloring
            return None

        def reduce_color_class(coloring):
            # Try to eliminate the highest color class by recoloring or Kempe swaps
            colors_used = set(coloring)
            if not colors_used:
                return coloring
            max_color = max(colors_used)
            if max_color == 0:
                return coloring  # Already minimal
            target_vertices = [v for v in range(n) if coloring[v] == max_color]
            random.shuffle(target_vertices)
            for v in target_vertices:
                neighbor_colors = set()
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        neighbor_colors.add(coloring[u])
                # Try direct reassignment to a lower color
                for c in range(max_color):
                    if c not in neighbor_colors:
                        coloring[v] = c
                        break
                else:
                    # Direct reassignment failed, try Kempe chains
                    for c in range(max_color):
                        # Attempt to swap along a Kempe chain (c, max_color) that contains v
                        chain_coloring = kempe_swap(coloring, c, max_color)
                        if chain_coloring is not None:
                            # After swap, check if v can take color c (should be free now)
                            neighbor_colors_after = set()
                            for u in neighbors[v]:
                                if chain_coloring[u] != -1:
                                    neighbor_colors_after.add(chain_coloring[u])
                            if c not in neighbor_colors_after:
                                return chain_coloring
            return coloring  # Could not reduce

        current = initial_coloring[:]
        best = current[:]
        best_count = count_colors(best)
        no_improve = 0

        for _ in range(max_iter):
            if no_improve >= 20:  # Early stop if no improvement
                break
            # Try to reduce the color count
            new_coloring = reduce_color_class(current)
            new_count = count_colors(new_coloring)
            if new_count < best_count:
                best = new_coloring[:]
                best_count = new_count
                no_improve = 0
            elif new_count < count_colors(current):
                current = new_coloring[:]
                no_improve = 0
            else:
                # No improvement, restart from a perturbed version
                # Apply random Kempe swaps to escape local optimum
                perturbed = current[:]
                for _ in range(10):
                    a, b = random.sample(range(best_count + 2), 2)  # Allow some extra colors
                    if a == b:
                        continue
                    swapped = kempe_swap(perturbed, a, b)
                    if swapped is not None:
                        perturbed = swapped
                current = perturbed
                no_improve += 1

        return best

    # Generate initial colorings
    colorings = [
        dsatur(),
        rlf(),
        welsh_powell()
    ]

    # Add random greedy orders for diversity
    for _ in range(30):  # Increased for better coverage
        order = list(range(n))
        random.shuffle(order)
        colorings.append(greedy_color(order))

    # Select best initial coloring (by number of colors used)
    def num_colors(col):
        return max(col) + 1 if n > 0 else 0

    best_coloring = min(colorings, key=num_colors)
    refined = iterated_local_search(best_coloring, max_iter=50)
    if num_colors(refined) < num_colors(best_coloring):
        best_coloring = refined

    return best_coloring

