import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and degree list
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        degree = [len(adj_list[i]) for i in range(n)]
    else:
        adj_list = adj
        degree = [len(adj_list[i]) for i in range(n)]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: count number of colors used
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # DSATUR implementation with optimized tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        neighbor_colors = [set() for _ in range(n)]
        uncolored = set(range(n))

        if uncolored:
            v = max(uncolored, key=lambda x: (degree[x], random.random()))
            color[v] = 0
            uncolored.remove(v)
            for u in adj_list[v]:
                if 0 not in neighbor_colors[u]:
                    neighbor_colors[u].add(0)
                    sat[u] += 1

        while uncolored:
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if len(candidates) == 1:
                v = candidates[0]
            else:
                # Tie-break: max degree in uncolored subgraph, then min index for determinism
                max_deg = -1
                deg_candidates = []
                for v in candidates:
                    d = sum(1 for u in adj_list[v] if u in uncolored)
                    if d > max_deg:
                        max_deg = d
                        deg_candidates = [v]
                    elif d == max_deg:
                        deg_candidates.append(v)
                if len(deg_candidates) == 1:
                    v = deg_candidates[0]
                else:
                    v = min(deg_candidates)  # Break ties by vertex index
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in adj_list[v]:
                if color[u] == -1:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        sat[u] += 1
        return color

    # RLF implementation (Largest First Independent Set) with optimized selection
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            v = max(uncolored, key=lambda x: (sum(1 for y in adj_list[x] if y in uncolored), random.random()))
            S = {v}
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any(u in adj_list[w] for w in S):
                    W.add(u)
                else:
                    U.add(u)
            while U:
                best_u = None
                best_score = -1
                tie_candidates = []
                for u in U:
                    score = sum(1 for w in adj_list[u] if w in W)
                    if score > best_score:
                        best_score = score
                        tie_candidates = [u]
                    elif score == best_score:
                        tie_candidates.append(u)
                if tie_candidates:
                    min_deg = float('inf')
                    min_candidates = []
                    for u in tie_candidates:
                        deg_u = sum(1 for w in adj_list[u] if w in U)
                        if deg_u < min_deg:
                            min_deg = deg_u
                            min_candidates = [u]
                        elif deg_u == min_deg:
                            min_candidates.append(u)
                    u = min(min_candidates)  # Break ties by vertex index
                else:
                    u = min(U)  # Deterministic fallback
                S.add(u)
                U.remove(u)
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        remaining = set(range(n))
        degree_copy = degree[:]
        order = []
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree_copy[v]
            if d <= max_deg:
                buckets[d].add(v)
        for _ in range(n):
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            for u in adj_list[v]:
                if u in remaining:
                    old_d = degree_copy[u]
                    if old_d <= max_deg and u in buckets[old_d]:
                        buckets[old_d].remove(u)
                    degree_copy[u] -= 1
                    new_d = degree_copy[u]
                    if new_d <= max_deg:
                        buckets[new_d].add(u)
            remaining.remove(v)
        return greedy_color(order[::-1])

    # Welsh-Powell ordering (by initial degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (degree[x], random.random()), reverse=True)
        return greedy_color(order)

    # Recursive DSATUR with restart and perturbation
    def recursive_dsatur(limit=7):
        best_coloring = None
        best_colors = float('inf')
        for _ in range(limit):
            color = [-1] * n
            sat = [0] * n
            neighbor_colors = [set() for _ in range(n)]
            uncolored = set(range(n))
            if uncolored:
                # Start with random vertex to break symmetry
                v = random.choice(list(uncolored))
                color[v] = 0
                uncolored.remove(v)
                for u in adj_list[v]:
                    if 0 not in neighbor_colors[u]:
                        neighbor_colors[u].add(0)
                        sat[u] += 1
            while uncolored:
                max_sat = -1
                candidates = []
                for v in uncolored:
                    if sat[v] > max_sat:
                        max_sat = sat[v]
                        candidates = [v]
                    elif sat[v] == max_sat:
                        candidates.append(v)
                if not candidates:
                    break  # should not happen
                if len(candidates) == 1:
                    v = candidates[0]
                else:
                    max_deg = -1
                    deg_candidates = []
                    for v in candidates:
                        d = sum(1 for u in adj_list[v] if u in uncolored)
                        if d > max_deg:
                            max_deg = d
                            deg_candidates = [v]
                        elif d == max_deg:
                            deg_candidates.append(v)
                    if len(deg_candidates) == 1:
                        v = deg_candidates[0]
                    else:
                        v = min(deg_candidates)  # Deterministic tie-break
                used = [False] * n
                for u in adj_list[v]:
                    if color[u] != -1:
                        used[color[u]] = True
                c = 0
                while c < n and used[c]:
                    c += 1
                color[v] = c
                uncolored.remove(v)
                for u in adj_list[v]:
                    if color[u] == -1:
                        if c not in neighbor_colors[u]:
                            neighbor_colors[u].add(c)
                            sat[u] += 1
            if is_valid(color):
                colors_used = count_colors(color)
                if colors_used < best_colors:
                    best_colors = colors_used
                    best_coloring = color[:]
        return best_coloring if best_coloring is not None else greedy_color(list(range(n)))

    # Iterated Local Search with Kempe chains
    def iterated_local_search(coloring, steps=30):
        current = coloring[:]
        current_colors = count_colors(current)
        best = current[:]
        best_colors = current_colors
        for _ in range(steps):
            # Kempe chain swap attempt
            improved = False
            colors_used = set(current)
            if len(colors_used) <= 1:
                break
            # Try to reduce the largest color class
            sorted_colors = sorted(colors_used, reverse=True)
            for target_color in sorted_colors:
                if improved:
                    break
                vertices = [v for v in range(n) if current[v] == target_color]
                random.shuffle(vertices)
                for v in vertices:
                    if improved:
                        break
                    neighbor_colors = set()
                    for u in adj_list[v]:
                        if current[u] != -1:
                            neighbor_colors.add(current[u])
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            # Direct move
                            current[v] = c
                            improved = True
                            break
                    if improved:
                        break
                    # Kempe chain
                    for c in range(target_color):
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if current[node] == target_color or current[node] == c:
                                component.add(node)
                                for u in adj_list[node]:
                                    if u not in visited and (current[u] == target_color or current[u] == c):
                                        stack.append(u)
                        conflict = False
                        for u in adj_list[v]:
                            if current[u] == c and u not in component:
                                conflict = True
                                break
                        if not conflict:
                            for node in component:
                                if current[node] == target_color:
                                    current[node] = c
                                elif current[node] == c:
                                    current[node] = target_color
                            improved = True
                            break
                    if improved:
                        break
            if not improved:
                # Random restart perturbation
                # Recolor a random vertex to a random color
                v = random.randrange(n)
                old_color = current[v]
                new_color = random.randrange(current_colors + 2)  # allow new color
                current[v] = new_color
                # Repair conflicts greedily
                for u in adj_list[v]:
                    if current[u] == new_color:
                        # Recolor u to avoid conflict
                        used = set()
                        for w in adj_list[u]:
                            if current[w] != -1:
                                used.add(current[w])
                        cu = 0
                        while cu in used:
                            cu += 1
                        current[u] = cu
            # Update best
            if is_valid(current):
                cols = count_colors(current)
                if cols < best_colors:
                    best_colors = cols
                    best = current[:]
        return best

    # Run all algorithms and select best valid coloring
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
