    except:
        pass
    # Recursive DSATUR
    try:
        col_rds = recursive_dsatur(limit=7)
        if is_valid(col_rds):
            candidates.append((count_colors(col_rds), col_rds))
    except:
        pass

    # If no candidate, fallback
    if not candidates:
        col_fallback = greedy_color(list(range(n)))
        if is_valid(col_fallback):
            candidates.append((count_colors(col_fallback), col_fallback))
        else:
            return list(range(n))

    # Select candidate with minimum colors
    min_colors = min(c[0] for c in candidates)
    best = [c[1] for c in candidates if c[0] == min_colors]
    # Apply iterated local search to the best candidate to try to improve
    improved = iterated_local_search(random.choice(best), steps=30)
    if is_valid(improved):
        return improved
    else:
        return random.choice(best) if best else [0]*n
